    /// accesses inside a static member that is being moved out of the decorated
    /// subclass, and run `apply` with it.
    ///
    /// Moving a static member (field/accessor initializer, private method or
    /// static block) into the generated `class extends _identity` wrapper (or
    /// into a closure) changes what `super` refers to at runtime. To preserve
    /// the original semantics we rewrite `super.foo` into a prototype-chain
    /// lookup rooted at the class reference variable, e.g.
    /// `_get(_get_prototype_of(_Derived), "foo", this)`.
    fn rewrite_static_super(
        &self,
        class_name: &Ident,
        apply: impl FnOnce(&mut SuperFieldAccessFolder),
    ) {
        let no_super_class = None;
        let mut folder = SuperFieldAccessFolder {
            class_name,
            constructor_this_mark: None,
            is_static: true,
            folding_constructor: false,
            in_nested_scope: false,
            in_injected_define_property_call: false,
            this_alias_mark: None,
            constant_super: false,
            super_class: &no_super_class,
            in_pat: false,
        };

        apply(&mut folder);
    }

    fn rewrite_super_for_moved_static_member(&self, function: &mut Function, class_name: &Ident) {
        self.rewrite_static_super(class_name, |folder| function.visit_mut_with(folder));
    }

    /// Rewrite `super` property accesses inside a moved static field/accessor
    /// initializer expression.
    fn rewrite_super_in_static_expr(&self, expr: &mut Expr, class_name: &Ident) {
        self.rewrite_static_super(class_name, |folder| expr.visit_mut_with(folder));
    }

    /// Rewrite `super` property accesses inside the statements of a moved static
    /// initialization block.
